import{bV as s,aL as e,u as n,G as t}from"./chunks/framework.DvBUyM1S.js";const b=JSON.parse('{"title":"GitHub仓库下载慢几种解决办法","description":"","frontmatter":{"title":"GitHub仓库下载慢几种解决办法","date":"2021-5-28","permalink":"/pages/95565e/","categories":["GitHub"],"tags":[null]},"headers":[],"relativePath":"06.工具/05.GitHub/05.GitHub仓库下载慢几种解决办法.md","filePath":"06.工具/05.GitHub/05.GitHub仓库下载慢几种解决办法.md","lastUpdated":1652179217000}'),i={name:"06.工具/05.GitHub/05.GitHub仓库下载慢几种解决办法.md"};function l(p,a,o,r,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="github仓库下载慢几种解决办法" tabindex="-1">GitHub仓库下载慢几种解决办法 <a class="header-anchor" href="#github仓库下载慢几种解决办法" aria-label="Permalink to &quot;GitHub仓库下载慢几种解决办法&quot;">​</a></h1><p><strong>目录</strong></p><ol><li>vps/代理</li><li>码云中转下载</li><li>cnpmjs镜像</li><li>hosts</li><li>GitClone 缓存加速(新)</li></ol><h2 id="科学的上网" tabindex="-1">科学的上网 <a class="header-anchor" href="#科学的上网" aria-label="Permalink to &quot;科学的上网&quot;">​</a></h2><p>全局上网后如果下载速度并没有显著提升的话，搭配代理<code>Proxifier</code>等工具。</p><h2 id="码云" tabindex="-1">码云 <a class="header-anchor" href="#码云" aria-label="Permalink to &quot;码云&quot;">​</a></h2><p>登录码云官网后点击 <code>+</code> 选择从GitHub导入仓库。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200712161533.jpg" alt="-w477" loading="lazy"></p><p>然后进入这个页面。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200712161535.jpg" alt="-w750" loading="lazy"></p><p>导入成功，复制url或者地址，用法和github一样。</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200712161542.jpg" alt="-w1052" loading="lazy"></p><h2 id="cnpmjs-镜像" tabindex="-1">cnpmjs 镜像 <a class="header-anchor" href="#cnpmjs-镜像" aria-label="Permalink to &quot;cnpmjs 镜像&quot;">​</a></h2><p>这个方法更加的简单,只需要修改你的路径<code>github.com</code>为<code>github.com.cnpmjs.org</code></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/qqlcx5/editor.git</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#改为</span></span>
<span class="line"><span>git clone https://github.com.cnpmjs.org/qqlcx5/editor.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="hosts" tabindex="-1">hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to &quot;hosts&quot;">​</a></h2><p><strong>解决办法</strong></p><p>直接找出github域名所对应的IP地址，直接添加在本地host中。这样每次请求gihub时就无须在向DNS查询地址了。</p><p><strong>DNS查找IP地址</strong></p><p>将下列的IP地址替换成点击对应的地址获取IP地址。</p><ul><li><p><a href="https://fastly.net.ipaddress.com/github.global.ssl.fastly.net" target="_blank" rel="noreferrer">github.global.ssl.fastly.net</a></p></li><li><p><a href="https://github.com.ipaddress.com/" target="_blank" rel="noreferrer">github.com</a></p></li><li><p><a href="https://amazonaws.com.ipaddress.com/github-cloud.s3.amazonaws.com" target="_blank" rel="noreferrer">github-cloud.s3.amazonaws.com</a></p></li></ul><p>例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>199.232.69.194 github.global.ssl.fastly.net </span></span>
<span class="line"><span>140.82.112.3 github.com</span></span>
<span class="line"><span>52.217.82.236 github-cloud.s3.amazonaws.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="window" tabindex="-1">window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;window&quot;">​</a></h3><p>在我的电脑复制下列地址回车键，看到<code>hosts</code>文件，然后复制我的桌面。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Windows\\System32\\drivers\\etc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将刚才的地址复制进去保存，然后将保存的文件拖拽到刚才的地址进行替换。（需要管理权限）</p><h3 id="mac" tabindex="-1">MAC <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;MAC&quot;">​</a></h3><p>按快捷键 <code>shift</code> + <code>option</code> + <code>G</code>弹出对话框，粘贴 <code>/etc/hosts</code>，回车键，看到host复一份修改，然后替换原来文件，类似上面window操作。</p><h3 id="通过工具快捷修改hosts" tabindex="-1">通过工具快捷修改hosts <a class="header-anchor" href="#通过工具快捷修改hosts" aria-label="Permalink to &quot;通过工具快捷修改hosts&quot;">​</a></h3><p>SwitchHosts开源地址: <a href="https://github.com/oldj/SwitchHosts/releases" target="_blank" rel="noreferrer">https://github.com/oldj/SwitchHosts/releases</a></p><p>MacOS下载懒人链接: <a href="https://github.com/oldj/SwitchHosts/releases/download/v3.5.4/SwitchHosts._macOS_3.5.4.5517.dmg" target="_blank" rel="noreferrer">SwitchHosts._macOS_3.5.4.5517.dmg</a></p><p>Windows下载懒人链接: <a href="https://github.com/oldj/SwitchHosts/releases/download/v3.5.4/SwitchHosts._windows_portable_3.5.4.5517.exe" target="_blank" rel="noreferrer">SwitchHosts._windows_portable_3.5.4.5517.exe</a></p><h3 id="刷新-dns-缓存" tabindex="-1">刷新 DNS 缓存 <a class="header-anchor" href="#刷新-dns-缓存" aria-label="Permalink to &quot;刷新 DNS 缓存&quot;">​</a></h3><p>在终端或CMD中，执行以下命令：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Window： ipconfig/flushdns</span></span>
<span class="line"><span>mac执行：sudo dscacheutil –flushcache</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="gitclone" tabindex="-1">GitClone <a class="header-anchor" href="#gitclone" aria-label="Permalink to &quot;GitClone&quot;">​</a></h2><p>当开发者经gitclone.com中转clone github上的代码库时，gitclone.com会对代码库进行mirror缓存，以后有开发者clone时，将直接从mirror缓存中获取数据，mirror将在每天夜间从github.com同步。 ​</p><h3 id="设置git的超时参数" tabindex="-1">设置git的超时参数 <a class="header-anchor" href="#设置git的超时参数" aria-label="Permalink to &quot;设置git的超时参数&quot;">​</a></h3><p>​ ​ 首先要设置git的超时参数，防止项目较大时，服务器端mirror时间过长导致git报504（超时） ​</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global http.lowSpeedLimit 0</span></span>
<span class="line"><span>git config --global http.lowSpeedTime 999999</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="方法1-修改url" tabindex="-1">方法1：修改URL <a class="header-anchor" href="#方法1-修改url" aria-label="Permalink to &quot;方法1：修改URL&quot;">​</a></h3><p>该仓库总大小30M左右，拿来作为实验对象。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github</span></span>
<span class="line"><span>https://github.com/qqlcx5/editor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GitClone</span></span>
<span class="line"><span>git clone https://gitclone.com/github.com/qqlcx5/editor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>大概在10秒内下载完成，觉得不错。</p><h3 id="方法二-修改git配置" tabindex="-1">方法二 修改git配置 <a class="header-anchor" href="#方法二-修改git配置" aria-label="Permalink to &quot;方法二 修改git配置&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global url.&quot;https://gitclone.com/github.com/&quot;.insteadOf https://github.com/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在这补充一点，官网推荐 <code>git config --global url.“https://gitclone.com/&quot;.insteadOf https://</code>，个人觉得不是友好，毕竟还有很多仓库，如果上面这样写的话，估计也会走<code>gitclone</code>通道。估计引发XX问题。</p><p>了解更多<a href="https://gitclone.com/" target="_blank" rel="noreferrer">前往gitclone官网</a></p><p>参考链接</p><p><a href="https://www.jianshu.com/p/0493dcc15d6f" target="_blank" rel="noreferrer">https://www.jianshu.com/p/0493dcc15d6f</a></p>`,51)])])}const u=s(i,[["render",l]]);export{b as __pageData,u as default};
